def matches(spec,branch,paths):
 if spec is None:return True
 if isinstance(spec,str):return True
 if 'branches' in spec and not any(fnmatch.fnmatchcase(branch,p) for p in spec['branches']):return False
 if 'tags' in spec and 'branches' not in spec:return False
 if 'paths' in spec and not any(fnmatch.fnmatchcase(f,p) for f in paths for p in spec['paths']):return False
 return True

def matrix_rows(matrix):
 if not matrix:return [{}]
 axes={k:v for k,v in matrix.items() if k not in ('include','exclude')};
 if not axes:return [dict(i) for i in matrix.get('include',[])] or [{}]
 rows=[dict(zip(axes,vs)) for vs in itertools.product(*axes.values())] if axes else []
 rows=[r for r in rows if not any(all(r.get(k)==v for k,v in ex.items()) for ex in matrix.get('exclude',[]))]
 for inc in matrix.get('include',[]):
  compatible=[r for r in rows if all(k not in axes or r[k]==v for k,v in inc.items())]
  if compatible:
   for r in compatible:r.update(inc)
  else:rows.append(dict(inc))
 return rows

